public static long[] computeConstantValue(Instance instance, List<Instruction> expr) {
        var stack = new ArrayDeque<long[]>();
        for (var instruction : expr) {
            switch (instruction.opcode()) {
                case I32_ADD:
                    {
                        var x = (int) stack.pop()[0];
                        var y = (int) stack.pop()[0];
                        stack.push(new long[] {x + y});
                        break;
                    }
                case I32_SUB:
                    {
                        var x = (int) stack.pop()[0];
                        var y = (int) stack.pop()[0];
                        stack.push(new long[] {y - x});
                        break;
                    }
                case I32_MUL:
                    {
                        var x = (int) stack.pop()[0];
                        var y = (int) stack.pop()[0];
                        int res = x * y;
                        stack.push(new long[] {res});
                        break;
                    }
                case I64_ADD:
                    {
                        var x = stack.pop()[0];
                        var y = stack.pop()[0];
                        stack.push(new long[] {x + y});
                        break;
                    }
                case I64_SUB:
                    {
                        var x = stack.pop()[0];
                        var y = stack.pop()[0];
                        stack.push(new long[] {y - x});
                        break;
                    }
                case I64_MUL:
                    {
                        var x = stack.pop()[0];
                        var y = stack.pop()[0];
                        stack.push(new long[] {x * y});
                        break;
                    }
                case V128_CONST:
                    {
                        stack.push(new long[] {instruction.operand(0), instruction.operand(1)});
                        break;
                    }
                case F32_CONST:
                case F64_CONST:
                case I32_CONST:
                case I64_CONST:
                case REF_FUNC:
                    {
                        stack.push(new long[] {instruction.operand(0)});
                        break;
                    }
                case REF_NULL:
                    {
                        stack.push(new long[] {Value.REF_NULL_VALUE});
                        break;
                    }
                case GLOBAL_GET:
                    {
                        var idx = (int) instruction.operand(0);
                        var global = instance.global(idx);
                        if (global == null) {
                            throw new InvalidException("unknown global");
                        }
                        if (global.getType().equals(ValType.V128)) {
                            stack.push(new long[] {global.getValueLow(), global.getValueHigh()});
                        } else {
                            stack.push(new long[] {global.getValueLow()});
                        }
                        break;
                    }
                case REF_I31:
                    {
                        var val = (int) stack.pop()[0];
                        stack.push(new long[] {Value.encodeI31(val)});
                        break;
                    }
                case STRUCT_NEW:
                    {
                        var typeIdx = (int) instruction.operand(0);
                        var structType =
                                instance.module()
                                        .typeSection()
                                        .getSubType(typeIdx)
                                        .compType()
                                        .structType();
                        var fieldCount = structType.fieldTypes().length;
                        var fields = new long[fieldCount];
                        for (int i = fieldCount - 1; i >= 0; i--) {
                            fields[i] = stack.pop()[0];
                        }
                        var struct = new WasmStruct(typeIdx, fields);
                        var refId = instance.registerGcRef(struct);
                        stack.push(new long[] {refId});
                        break;
                    }
                case STRUCT_NEW_DEFAULT:
                    {
                        var typeIdx = (int) instruction.operand(0);
                        var structType =
                                instance.module()
                                        .typeSection()
                                        .getSubType(typeIdx)
                                        .compType()
                                        .structType();
                        var fieldCount = structType.fieldTypes().length;
                        var fields = new long[fieldCount];
                        for (int i = 0; i < fieldCount; i++) {
                            var ft = structType.fieldTypes()[i];
                            if (ft.storageType().valType() != null
                                    && ft.storageType().valType().isReference()) {
                                fields[i] = Value.REF_NULL_VALUE;
                            }
                        }
                        var struct = new WasmStruct(typeIdx, fields);
                        var refId = instance.registerGcRef(struct);
                        stack.push(new long[] {refId});
                        break;
                    }
                case ARRAY_NEW:
                    {
                        var typeIdx = (int) instruction.operand(0);
                        var len = (int) stack.pop()[0];
                        var fillVal = stack.pop()[0];
                        var elements = new long[len];
                        Arrays.fill(elements, fillVal);
                        var array = new WasmArray(typeIdx, elements);
                        var refId = instance.registerGcRef(array);
                        stack.push(new long[] {refId});
                        break;
                    }
                case ARRAY_NEW_DEFAULT:
                    {
                        var typeIdx = (int) instruction.operand(0);
                        var len = (int) stack.pop()[0];
                        var at =
                                instance.module()
                                        .typeSection()
                                        .getSubType(typeIdx)
                                        .compType()
                                        .arrayType();
                        var elements = new long[len];
                        if (at.fieldType().storageType().valType() != null
                                && at.fieldType().storageType().valType().isReference()) {
                            Arrays.fill(elements, Value.REF_NULL_VALUE);
                        }
                        var array = new WasmArray(typeIdx, elements);
                        var refId = instance.registerGcRef(array);
                        stack.push(new long[] {refId});
                        break;
                    }
                case ARRAY_NEW_FIXED:
                    {
                        var typeIdx = (int) instruction.operand(0);
                        var len = (int) instruction.operand(1);
                        var elements = new long[len];
                        for (int i = len - 1; i >= 0; i--) {
                            elements[i] = stack.pop()[0];
                        }
                        var array = new WasmArray(typeIdx, elements);
                        var refId = instance.registerGcRef(array);
                        stack.push(new long[] {refId});
                        break;
                    }
                case ANY_CONVERT_EXTERN:
                case EXTERN_CONVERT_ANY:
                    {
                        // Identity operations at runtime
                        break;
                    }
                case END:
                    {
                        break;
                    }
                default:
                    throw new MalformedException(
                            "Invalid instruction in constant value" + instruction);
            }
        }

        return stack.pop();
    }

public Map<String, CompilationUnit> generate() {
        Map<String, CompilationUnit> result = new LinkedHashMap<>();
        String prefix = packageName.isEmpty() ? "" : packageName + ".";

        var exportsCu = newCu();
        exportsCu.addImport("com.dylibso.chicory.runtime.Instance");

        var processorName = new StringLiteralExpr(generatorName);
        var exportsClass =
                exportsCu
                        .addClass(typeName + "_ModuleExports", Modifier.Keyword.PUBLIC)
                        .setPublic(true)
                        .addSingleMemberAnnotation(Generated.class, processorName);
        result.put(prefix + typeName + "_ModuleExports", exportsCu);

        var functionImports =
                module.importSection().stream()
                        .filter(i -> i.importType() == ExternalType.FUNCTION)
                        .map(i -> (FunctionImport) i)
                        .toArray(FunctionImport[]::new);

        var exportsConstructor = exportsClass.addConstructor(Modifier.Keyword.PUBLIC);
        exportsConstructor.addParameter(parseType("Instance"), "instance");

        // generate module exports
        var exportCallHandle =
                new MethodCallExpr(new NameExpr("instance"), "exports", NodeList.nodeList());
        var exportNames = new ArrayList<String>();

        for (int i = 0; i < module.exportSection().exportCount(); i++) {
            var export = module.exportSection().getExport(i);

            var name =
                    deduplicatedMethodName(
                            CodegenUtils.snakeCaseToCamelCase(export.name(), false), exportNames);
            exportNames.add(name);

            var exportFieldName = new NameExpr("field_" + name);
            Type exportFieldType = null;
            switch (export.exportType()) {
                case MEMORY:
                    exportFieldType = parseType("Memory");
                    break;
                case GLOBAL:
                    exportFieldType = parseType("GlobalInstance");
                    break;
                case TABLE:
                    exportFieldType = parseType("TableInstance");
                    break;
                case FUNCTION:
                    exportFieldType = parseType("ExportFunction");
                    break;
            }
            exportsClass.addField(
                    exportFieldType,
                    exportFieldName.getName().asString(),
                    Modifier.Keyword.PRIVATE,
                    Modifier.Keyword.FINAL);

            var exportMethod = exportsClass.addMethod(name, Modifier.Keyword.PUBLIC);

            var exportMethodBodyGen = exportMethodBodyGen(exportCallHandle, export.name());

            if (export.exportType() == ExternalType.MEMORY) {
                exportsCu.addImport("com.dylibso.chicory.runtime.Memory");

                exportsConstructor
                        .getBody()
                        .addStatement(
                                new AssignExpr(
                                        exportFieldName,
                                        exportMethodBodyGen.apply("memory"),
                                        AssignExpr.Operator.ASSIGN));

                exportMethod.setType(exportFieldType);
                exportMethod.createBody().addStatement(new ReturnStmt(exportFieldName));
                continue;
            } else if (export.exportType() == ExternalType.GLOBAL) {
                exportsCu.addImport("com.dylibso.chicory.runtime.GlobalInstance");

                exportsConstructor
                        .getBody()
                        .addStatement(
                                new AssignExpr(
                                        exportFieldName,
                                        exportMethodBodyGen.apply("global"),
                                        AssignExpr.Operator.ASSIGN));

                exportMethod.setType(exportFieldType);
                exportMethod.createBody().addStatement(new ReturnStmt(exportFieldName));
                continue;
            } else if (export.exportType() == ExternalType.TABLE) {
                exportsCu.addImport("com.dylibso.chicory.runtime.TableInstance");

                exportsConstructor
                        .getBody()
                        .addStatement(
                                new AssignExpr(
                                        exportFieldName,
                                        exportMethodBodyGen.apply("table"),
                                        AssignExpr.Operator.ASSIGN));

                exportMethod.setType(exportFieldType);
                exportMethod.createBody().addStatement(new ReturnStmt(exportFieldName));
                continue;
            }
            // it should be a function here
            assert (export.exportType() == ExternalType.FUNCTION);
            exportsCu.addImport("com.dylibso.chicory.runtime.ExportFunction");

            var funcType =
                    (export.index() >= functionImports.length)
                            ? module.functionSection()
                                    .getFunctionType(export.index() - functionImports.length)
                            : functionImports[export.index()].typeIndex();
            var exportType = module.typeSection().getType(funcType);

            var argPrefix = "arg";
            var handleCallArguments = new ArrayList<Expression>();
            for (var pIdx = 0; pIdx < exportType.params().size(); pIdx++) {
                var param = exportType.params().get(pIdx);
                var argName = argPrefix + pIdx;
                var javaType = javaClassFromValueType(param);
                // signature
                exportMethod.addParameter(javaType, argName);
                // body invocation call arguments
                var argExpr = new NameExpr(argName);
                handleCallArguments.add(toLong(param, argExpr, exportsCu));
            }

            var methodBody = exportMethod.createBody();
            var exportCall =
                    new MethodCallExpr(
                            exportCallHandle,
                            "function",
                            NodeList.nodeList(new StringLiteralExpr(export.name())));
            exportsConstructor
                    .getBody()
                    .addStatement(
                            new AssignExpr(
                                    exportFieldName, exportCall, AssignExpr.Operator.ASSIGN));

            var exportApplyHandle =
                    new MethodCallExpr(
                            exportFieldName, "apply", NodeList.nodeList(handleCallArguments));

            if (exportType.returns().size() == 0) {
                exportMethod.setType(void.class);
                methodBody.addStatement(exportApplyHandle).addStatement(new ReturnStmt());
            } else if (exportType.returns().size() > 1) {
                exportMethod.setType(long[].class);
                methodBody.addStatement(new ReturnStmt(exportApplyHandle));
            } else {
                exportMethod.setType(javaClassFromValueType(exportType.returns().get(0)));
                methodBody.addStatement(
                        new AssignExpr(
                                new VariableDeclarationExpr(parseType("long"), "result"),
                                new ArrayAccessExpr(exportApplyHandle, new IntegerLiteralExpr("0")),
                                AssignExpr.Operator.ASSIGN));
                methodBody.addStatement(
                        new ReturnStmt(
                                fromLong(
                                        exportType.returns().get(0),
                                        new NameExpr("result"),
                                        exportsCu)));
            }
        }

        // generate module imports
        if (module.importSection() != null && module.importSection().importCount() > 0) {
            var importsCu = newCu();
            var importsInterface =
                    importsCu
                            .addInterface(typeName + "_ModuleImports")
                            .setPublic(true)
                            .addSingleMemberAnnotation(Generated.class, processorName);
            result.put(prefix + typeName + "_ModuleImports", importsCu);

            // group-by module name
            Map<String, List<Import>> importedModules = new HashMap<>();
            for (int i = 0; i < module.importSection().importCount(); i++) {
                var imprt = module.importSection().getImport(i);

                importedModules.computeIfAbsent(imprt.module(), ignored -> new ArrayList<>());
                importedModules.computeIfPresent(
                        imprt.module(),
                        (k, v) -> {
                            v.add(imprt);
                            return v;
                        });
            }

            if (importedModules.size() > 0) {
                var toImportValuesBody = new BlockStmt();
                toImportValuesBody.addStatement(
                        new AssignExpr(
                                new VariableDeclarationExpr(
                                        parseType("ImportValues.Builder"), "imports"),
                                new MethodCallExpr(new NameExpr("ImportValues"), "builder"),
                                AssignExpr.Operator.ASSIGN));

                for (var imprt : importedModules.entrySet()) {
                    var importClassName =
                            typeName
                                    + "_"
                                    + CodegenUtils.snakeCaseToCamelCase(imprt.getKey(), true);
                    var importClassMethod =
                            importsInterface.addMethod(
                                    CodegenUtils.snakeCaseToCamelCase(imprt.getKey(), false));
                    importClassMethod.removeBody();
                    importClassMethod.setType(importClassName);

                    var cu = newCu();
                    var importInterface =
                            cu.addInterface(importClassName)
                                    .setPublic(true)
                                    .addSingleMemberAnnotation(Generated.class, processorName);
                    result.put(prefix + importClassName, cu);

                    for (var importedFun : imprt.getValue()) {
                        var importMethod =
                                importInterface.addMethod(
                                        CodegenUtils.snakeCaseToCamelCase(
                                                importedFun.name(), false));

                        var importFunctionCall =
                                new MethodCallExpr(
                                        new MethodCallExpr(imprt.getKey()), importedFun.name());
                        java.util.function.Function<String, Expression> importObj =
                                importObjType ->
                                        new ObjectCreationExpr(
                                                null,
                                                parseClassOrInterfaceType(importObjType),
                                                NodeList.nodeList(
                                                        new StringLiteralExpr(imprt.getKey()),
                                                        new StringLiteralExpr(importedFun.name()),
                                                        importFunctionCall));

                        if (importedFun.importType() == ExternalType.MEMORY) {
                            cu.addImport("com.dylibso.chicory.runtime.Memory");
                            importMethod.setType("Memory");
                            importMethod.removeBody();

                            importsCu.addImport("com.dylibso.chicory.runtime.ImportMemory");
                            toImportValuesBody.addStatement(
                                    new MethodCallExpr(
                                            new NameExpr("imports"),
                                            "addMemory",
                                            NodeList.nodeList(importObj.apply("ImportMemory"))));
                            continue;
                        } else if (importedFun.importType() == ExternalType.GLOBAL) {
                            cu.addImport("com.dylibso.chicory.runtime.GlobalInstance");
                            importMethod.setType("GlobalInstance");
                            importMethod.removeBody();

                            importsCu.addImport("com.dylibso.chicory.runtime.ImportGlobal");
                            toImportValuesBody.addStatement(
                                    new MethodCallExpr(
                                            new NameExpr("imports"),
                                            "addGlobal",
                                            NodeList.nodeList(importObj.apply("ImportGlobal"))));
                            continue;
                        } else if (importedFun.importType() == ExternalType.TABLE) {
                            cu.addImport("com.dylibso.chicory.runtime.TableInstance");
                            importMethod.setType("TableInstance");
                            importMethod.removeBody();

                            importsCu.addImport("com.dylibso.chicory.runtime.ImportTable");
                            toImportValuesBody.addStatement(
                                    new MethodCallExpr(
                                            new NameExpr("imports"),
                                            "addTable",
                                            NodeList.nodeList(importObj.apply("ImportTable"))));
                            continue;
                        }
                        // we now know it's a function
                        assert (importedFun.importType() == ExternalType.FUNCTION);
                        // needed to generate the functions signatures
                        importsCu.addImport(List.class);
                        importsCu.addImport(ValType.class);
                        importsCu.addImport("com.dylibso.chicory.runtime.Instance");
                        importsCu.addImport("com.dylibso.chicory.runtime.HostFunction");

                        var importType =
                                module.typeSection()
                                        .getType(((FunctionImport) importedFun).typeIndex());
                        importMethod.removeBody();

                        // build lambda return
                        var functionBodyStatement = new BlockStmt();

                        List<Expression> parameters = new ArrayList<>();
                        for (int i = 0; i < importType.params().size(); i++) {
                            var p = importType.params().get(i);

                            parameters.add(
                                    fromLong(
                                            p,
                                            new ArrayAccessExpr(
                                                    new NameExpr("args"),
                                                    new IntegerLiteralExpr(Integer.toString(i))),
                                            importsCu));
                        }

                        var importApplyHandle =
                                new MethodCallExpr(
                                        new MethodCallExpr(
                                                CodegenUtils.snakeCaseToCamelCase(
                                                        imprt.getKey(), false)),
                                        CodegenUtils.snakeCaseToCamelCase(
                                                importedFun.name(), false),
                                        NodeList.nodeList(parameters));

                        if (importType.returns().size() == 0) {
                            importMethod.setType(void.class);
                            functionBodyStatement.addStatement(importApplyHandle);
                            functionBodyStatement.addStatement(
                                    new ReturnStmt(new NullLiteralExpr()));
                        } else if (importType.returns().size() == 1) {
                            importMethod.setType(
                                    javaClassFromValueType(importType.returns().get(0)));
                            functionBodyStatement.addStatement(
                                    new ReturnStmt(
                                            new ArrayCreationExpr(
                                                    parseType("long"),
                                                    NodeList.nodeList(new ArrayCreationLevel()),
                                                    new ArrayInitializerExpr(
                                                            NodeList.nodeList(
                                                                    toLong(
                                                                            importType
                                                                                    .returns()
                                                                                    .get(0),
                                                                            importApplyHandle,
                                                                            importsCu))))));
                        } else {
                            importMethod.setType(long[].class);
                            functionBodyStatement.addStatement(new ReturnStmt(importApplyHandle));
                        }

                        var importedHostFunctionBinding =
                                new ObjectCreationExpr(
                                        null,
                                        parseClassOrInterfaceType("HostFunction"),
                                        NodeList.nodeList(
                                                new StringLiteralExpr(imprt.getKey()),
                                                new StringLiteralExpr(importedFun.name()),
                                                listOfValueTypes(importType.params()),
                                                listOfValueTypes(importType.returns()),
                                                // (Instance instance, long... args) -> null;
                                                new LambdaExpr(
                                                        NodeList.nodeList(
                                                                new Parameter(
                                                                        parseType("Instance"),
                                                                        new SimpleName("instance")),
                                                                new Parameter(
                                                                                parseType("long"),
                                                                                "args")
                                                                        .setVarArgs(true)),
                                                        functionBodyStatement)));

                        toImportValuesBody.addStatement(
                                new MethodCallExpr(
                                        new NameExpr("imports"),
                                        "addFunction",
                                        NodeList.nodeList(importedHostFunctionBinding)));

                        var argPrefix = "arg";
                        for (var pIdx = 0; pIdx < importType.params().size(); pIdx++) {
                            var param = importType.params().get(pIdx);
                            var argName = argPrefix + pIdx;
                            // signature
                            importMethod.addParameter(javaClassFromValueType(param), argName);
                        }
                    }
                }
                var toImportsBuilder = new MethodCallExpr(new NameExpr("imports"), "build");
                toImportValuesBody.addStatement(new ReturnStmt(toImportsBuilder));

                var toImportValuesMethod =
                        importsInterface.addMethod("toImportValues", Modifier.Keyword.DEFAULT);
                importsCu.addImport("com.dylibso.chicory.runtime.ImportValues");
                toImportValuesMethod.setType("ImportValues");
                toImportValuesMethod.setBody(toImportValuesBody);
            }
        }

        return result;
    }

public CompilationUnit generate(String name, Wast wast, String wasmClasspath) {
        var cu = new CompilationUnit("com.dylibso.chicory.test.gen");
        var testName =
                "SpecV1" + StringUtils.capitalize(StringUtils.escapedCamelCase(name)) + "Test";

        // all the imports
        // junit imports
        cu.addImport("java.io.File");
        cu.addImport("org.junit.jupiter.api.Disabled");
        cu.addImport("org.junit.jupiter.api.Test");
        cu.addImport("org.junit.jupiter.api.DisplayName");
        cu.addImport("org.junit.jupiter.api.MethodOrderer");
        cu.addImport("org.junit.jupiter.api.TestMethodOrder");
        cu.addImport("org.junit.jupiter.api.Order");
        cu.addImport("org.junit.jupiter.api.TestInstance");
        cu.addImport("org.junit.jupiter.api.Assertions.assertArrayEquals", true, false);
        cu.addImport("org.junit.jupiter.api.Assertions.assertEquals", true, false);
        cu.addImport("org.junit.jupiter.api.Assertions.assertNotEquals", true, false);
        cu.addImport("org.junit.jupiter.api.Assertions.assertNotNull", true, false);
        cu.addImport("org.junit.jupiter.api.Assertions.assertThrows", true, false);
        cu.addImport("org.junit.jupiter.api.Assertions.assertTrue", true, false);
        cu.addImport("org.junit.jupiter.api.Assertions.assertDoesNotThrow", true, false);

        // testing imports
        cu.addImport("com.dylibso.chicory.testing.TestModule");
        cu.addImport("com.dylibso.chicory.testing.ArgsAdapter");

        // runtime imports
        cu.addImport("com.dylibso.chicory.wasm.ChicoryException");
        cu.addImport("com.dylibso.chicory.runtime.WasmException");
        cu.addImport("com.dylibso.chicory.runtime.ExportFunction");
        cu.addImport("com.dylibso.chicory.runtime.Instance");

        // base imports
        cu.addImport("com.dylibso.chicory.wasm.InvalidException");
        cu.addImport("com.dylibso.chicory.wasm.MalformedException");
        cu.addImport("com.dylibso.chicory.wasm.UninstantiableException");
        cu.addImport("com.dylibso.chicory.wasm.UnlinkableException");
        cu.addImport("com.dylibso.chicory.wasm.types.Value");

        cu.addImport("com.dylibso.chicory.wasm.types.Value.REF_NULL_VALUE", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.vecTo8", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.vecTo16", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.vecTo32", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.vecToF32", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.vecToF64", true, false);

        cu.addImport("com.dylibso.chicory.wasm.types.Value.i8ToVec", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.i16ToVec", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.i32ToVec", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.i64ToVec", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.f64ToVec", true, false);
        cu.addImport("com.dylibso.chicory.wasm.types.Value.f32ToVec", true, false);

        // import for Store instance
        cu.addImport("com.dylibso.chicory.runtime.Store");
        // import for shared Spectest host module
        cu.addImport("com.dylibso.chicory.testing.Spectest");

        var testClass = cu.addClass(testName);
        testClass.addSingleMemberAnnotation(
                "TestMethodOrder", new NameExpr("MethodOrderer.OrderAnnotation.class"));
        testClass.addSingleMemberAnnotation(
                "TestInstance",
                new FieldAccessExpr(
                        new FieldAccessExpr(new NameExpr("TestInstance"), "Lifecycle"),
                        "PER_CLASS"));

        MethodDeclaration method;
        int testNumber = 0;
        int moduleInstantiationNumber = 0;
        String lastModuleVarName = null;
        int fallbackVarNumber = 0;

        var excludedMethods =
                excludedTests.stream()
                        .filter(t -> t.startsWith(testName))
                        .map(t -> t.substring(testName.length() + 1))
                        .collect(Collectors.toList());

        testClass.addFieldWithInitializer(
                "Store",
                "store",
                new NameExpr("new Store().addImportValues(Spectest.toImportValues())"));

        String currentWasmFile = null;
        for (var cmd : wast.commands()) {
            switch (cmd.type()) {
                case MODULE:
                    {
                        currentWasmFile = getWasmFile(cmd, wasmClasspath);
                        lastModuleVarName = TEST_MODULE_NAME + moduleInstantiationNumber;
                        String lastInstanceVarName = lastModuleVarName + "Instance";
                        moduleInstantiationNumber++;
                        if (cmd.name() != null) {
                            lastModuleVarName = cmd.name().replace("$", "");
                            lastInstanceVarName = cmd.name().replace("$", "") + "Instance";
                        }
                        testClass.addFieldWithInitializer(
                                "Instance",
                                lastInstanceVarName,
                                new NullLiteralExpr(),
                                Modifier.Keyword.PUBLIC,
                                Modifier.Keyword.STATIC);

                        var instantiateMethodName = "instantiate_" + lastInstanceVarName;
                        var instantiateMethod =
                                testClass.addMethod(instantiateMethodName, Modifier.Keyword.PUBLIC);
                        // It needs to be a test to be executed
                        instantiateMethod.addAnnotation("Test");
                        instantiateMethod.addSingleMemberAnnotation(
                                "Order", new IntegerLiteralExpr(Integer.toString(testNumber++)));
                        instantiateMethod.addSingleMemberAnnotation(
                                "DisplayName",
                                new StringLiteralExpr(
                                        formatWastFileCoordinates(
                                                wast.sourceFilename().getName(),
                                                cmd.line(),
                                                cmd.filename())));

                        instantiateMethod.setBody(
                                new BlockStmt()
                                        .addStatement(
                                                new AssignExpr(
                                                        new NameExpr(lastInstanceVarName),
                                                        generateModuleInstantiation(
                                                                currentWasmFile,
                                                                getExcluded(
                                                                        CommandType.ASSERT_INVALID,
                                                                        name)),
                                                        AssignExpr.Operator.ASSIGN)));
                        break;
                    }
                case ACTION:
                case ASSERT_RETURN:
                case ASSERT_TRAP:
                case ASSERT_EXHAUSTION:
                case ASSERT_EXCEPTION:
                    {
                        method =
                                createTestMethod(
                                        wast.sourceFilename().getName(),
                                        cmd,
                                        testClass,
                                        testNumber++,
                                        excludedMethods);

                        var baseVarName = StringUtils.escapedCamelCase(cmd.action().field());
                        var varNum = fallbackVarNumber++;
                        var varName = "var" + (baseVarName.isEmpty() ? varNum : baseVarName);
                        String moduleName = lastModuleVarName;
                        if (cmd.action().module() != null) {
                            moduleName = cmd.action().module().replace("$", "");
                        }
                        var fieldExport = generateFieldExport(varName, cmd, moduleName);
                        if (fieldExport.isPresent()) {
                            method.getBody().get().addStatement(fieldExport.get());
                        }

                        if (cmd.type() == CommandType.ACTION) {
                            for (var expr : generateInvoke(varName, cmd)) {
                                method.getBody().get().addStatement(expr);
                            }
                        } else {
                            for (var expr :
                                    generateAssert(varName, cmd, lastModuleVarName + "Instance")) {
                                method.getBody().get().addStatement(expr);
                            }
                        }
                        break;
                    }
                case REGISTER:
                    String lastInstanceVarName = lastModuleVarName + "Instance";

                    generateRegisterInstance(cmd.as(), lastInstanceVarName);

                    var instantiateMethodName = "register_" + lastInstanceVarName;
                    var instantiateMethod =
                            testClass.addMethod(instantiateMethodName, Modifier.Keyword.PUBLIC);
                    // It needs to be a test to be executed
                    instantiateMethod.addAnnotation("Test");
                    instantiateMethod.addSingleMemberAnnotation(
                            "Order", new IntegerLiteralExpr(Integer.toString(testNumber++)));

                    instantiateMethod.setBody(
                            new BlockStmt()
                                    .addStatement(
                                            generateRegisterInstance(
                                                    cmd.as(), lastInstanceVarName)));

                    break;
                case ASSERT_MALFORMED:
                case ASSERT_INVALID:
                case ASSERT_UNINSTANTIABLE:
                case ASSERT_UNLINKABLE:
                    {
                        method =
                                createTestMethod(
                                        wast.sourceFilename().getName(),
                                        cmd,
                                        testClass,
                                        testNumber++,
                                        excludedMethods);
                        generateAssertThrows(
                                wasmClasspath,
                                cmd,
                                method,
                                getExcluded(cmd.type(), name),
                                getExceptionType(cmd.type()));
                        break;
                    }
                default:
                    throw new IllegalArgumentException(
                            "command type not yet supported " + cmd.type());
            }
        }

        return cu;
    }

class_constructor:
public JavaTestGen(
            List<String> excludedTests,
            List<String> excludedMalformedWasts,
            List<String> excludedInvalidWasts,
            List<String> excludedUninstantiableWasts,
            List<String> excludedUnlinkableWasts) {
        this.excludedTests = excludedTests;
        this.excludedMalformedWasts = excludedMalformedWasts;
        this.excludedInvalidWasts = excludedInvalidWasts;
        this.excludedUninstantiableWasts = excludedUninstantiableWasts;
        this.excludedUnlinkableWasts = excludedUnlinkableWasts;
    }
